class _LikeButtonState extends State<LikeButton> {
  late int _likes = widget.initialLikes;
  bool _liked = false;

  void _toggle() {
    setState(() {                       // mutate inside setState so Flutter rebuilds
      _liked = !_liked;
      _likes += _liked ? 1 : -1;
    });
  }

  @override
  Widget build(BuildContext context) {
    return TextButton.icon(
      onPressed: _toggle,
