class Cart {
  final _items = <String, int>{};
  void add(String sku, {int qty = 1}) {
    if (qty <= 0) throw ArgumentError.value(qty, 'qty', 'must be positive');
    _items.update(sku, (v) => v + qty, ifAbsent: () => qty);
  }
  int get count => _items.values.fold(0, (a, b) => a + b);
}

