    test('starts empty', () => expect(cart.count, 0));

    test('adds and accumulates quantities', () {
      cart.add('A', qty: 2);
      cart.add('A');
      cart.add('B');
      expect(cart.count, 4);
    });

    test('rejects non-positive quantity', () {
      expect(() => cart.add('A', qty: 0), throwsArgumentError);
    });
